-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/zones/Western_Adoulin/npcs/Nikkhail.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Nikkhail.lua",["SHA256"]="edadbeb4128091847fff4ff87cf71062074d70953e378285b8dcf31581cfaacb",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Nikkhail\n--  Involved With Quest: 'A Thirst for the Ages'\n-- !pos -101 3 9 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local atfta = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_THIRST_FOR_THE_AGES)\n    local atftaNeedKI = player:getCharVar('ATFTA_Status') < 2 and not player:hasKeyItem(xi.keyItem.COPY_OF_THE_ALLIANCE_AGREEMENT)\n    local soaMission = player:getCurrentMission(xi.mission.log_id.SOA)\n\n    if soaMission >= xi.mission.id.soa.LIFE_ON_THE_FRONTIER then\n        if atfta == xi.questStatus.QUEST_ACCEPTED and atftaNeedKI then\n            -- Progresses Quest: 'A Thirst for the Ages'\n            player:startEvent(5053)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 5053 then\n        npcUtil.giveKeyItem(player, xi.keyItem.COPY_OF_THE_ALLIANCE_AGREEMENT)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Oka_Qhantari.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Oka_Qhantari.lua",["SHA256"]="957d21140d4f773c393e856da1481f757d0c9a37a888a3bc09c0b7d3b80deac0",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Oka Qhantari\n--  Involved With Quest: 'Order Up'\n-- !pos -30 3 -6 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local orderUp = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.ORDER_UP)\n    local orderOkaQhantari = utils.mask.getBit(player:getCharVar('Order_Up_NPCs'), 9)\n\n    if orderUp == xi.questStatus.QUEST_ACCEPTED and not orderOkaQhantari then\n        -- Progresses Quest: 'Order Up'\n        player:startEvent(71)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 71 then\n        -- Progresses Quest: 'Order Up'\n        player:setCharVar('Order_Up_NPCs', utils.mask.setBit(player:getCharVar('Order_Up_NPCs'), 9, true))\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Pagnelle.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Pagnelle.lua",["SHA256"]="c67289a295d5f97314782120d4e2d7322d2ec5cdc71eb0d412ec221ba0a6535c",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Pagnelle\n-- !pos -8 0 -100 256\n-----------------------------------\nlocal ID = zones[xi.zone.WESTERN_ADOULIN]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local raptorRapture = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.RAPTOR_RAPTURE)\n    local raptorRaptureStatus = player:getCharVar('Raptor_Rapture_Status')\n\n    if raptorRapture == xi.questStatus.QUEST_AVAILABLE then\n        if raptorRaptureStatus < 3 then\n            -- Starts chain of events for the introduction CS for Quest: 'Raptor Rapture'.\n            -- If player somehow doesn't finish the chain of events, they can just talk to Pagnelle again to retry.\n            player:setCharVar('Raptor_Rapture_Status', 1)\n            player:startEvent(5032)\n        else\n            -- Player has finished introductory CS event chain, but didn't accept the quest.\n            -- Offers Quest: 'Raptor Rapture' if player has yet to accept it.\n            player:startEvent(5061)\n        end\n    elseif raptorRapture == xi.questStatus.QUEST_ACCEPTED then\n        if raptorRaptureStatus == 4 then\n            -- Reminder during Quest: 'Raptor Rapture', speak to Ilney.\n            player:startEvent(5033)\n        elseif raptorRaptureStatus == 5 then\n            -- Progresses Quest: 'Raptor Rapture', spoke to Ilney.\n            player:startEvent(5035)\n        elseif raptorRaptureStatus == 6 then\n            local hasRockberries = player:hasKeyItem(xi.keyItem.ROCKBERRY1) and player:hasKeyItem(xi.keyItem.ROCKBERRY2) and player:hasKeyItem(xi.keyItem.ROCKBERRY3)\n            if hasRockberries then\n                -- Progresses Quest: 'Raptor Rapture', turning in rockberries.\n                player:startEvent(5037)\n            else\n                -- Reminder during Quest: 'Raptor Rapture', bring rockberries.\n                player:startEvent(5036)\n            end\n        elseif raptorRaptureStatus == 7 then\n            -- Reminder during Quest: 'Raptor Rapture', go to Rala.\n            player:startEvent(5038)\n        elseif raptorRaptureStatus == 8 then\n            -- Finishes Quest: 'Raptor Rapture'\n            player:startEvent(5039)\n        end\n    else\n        if player:needToZone() then\n            -- Dialogue after finishing Quest: 'Raptor Rapture', before zoning\n            player:startEvent(5040)\n        else\n            -- Dialogue after finishing Quest: 'Raptor Rapture', after zoning\n            player:startEvent(5041)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 5032 then\n        -- Warps player to Rala Waterways to continue intrductory CS for Quest: 'Raptor Rapture'\n        player:setPos(0, 0, 0, 0, 258)\n    elseif csid == 5061 and option == 1 then\n        -- Starts Quest: 'Raptor Rapture'\n        player:addQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.RAPTOR_RAPTURE)\n        player:setCharVar('Raptor_Rapture_Status', 4)\n    elseif csid == 5035 then\n        -- Progresses Quest: 'Raptor Rapture', spoke to Ilney, now need rockberries.\n        player:setCharVar('Raptor_Rapture_Status', 6)\n    elseif csid == 5037 then\n        -- Progresses Quest: 'Raptor Rapture', brought rockberries, now need to go to Rala.\n        player:delKeyItem(xi.keyItem.ROCKBERRY1)\n        player:delKeyItem(xi.keyItem.ROCKBERRY2)\n        player:delKeyItem(xi.keyItem.ROCKBERRY3)\n        player:setCharVar('Raptor_Rapture_Status', 7)\n    elseif csid == 5039 then\n        -- Finishing Quest: 'Raptor Rapture'\n        player:setCharVar('Raptor_Rapture_Status', 0)\n        player:completeQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.RAPTOR_RAPTURE)\n        player:addCurrency('bayld', 1000 * xi.settings.main.BAYLD_RATE)\n        player:messageSpecial(ID.text.BAYLD_OBTAINED, 1000 * xi.settings.main.BAYLD_RATE)\n\n        -- TODO: Verify fame value added\n        player:addFame(xi.fameArea.ADOULIN, 30)\n        player:needToZone(true)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Ruth.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Ruth.lua",["SHA256"]="54a53cf44145c9dfecfdf514bdc0b87529c9252a9625b7c95bef321fbbfe9b15",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Ruth\n-- Involved With Quest: 'A Pioneers Best (Imaginary) Friend'\n-- !pos -144 4 -10 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:getCurrentMission(xi.mission.log_id.SOA) >= xi.mission.id.soa.LIFE_ON_THE_FRONTIER then\n        if\n            player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.A_PIONEERS_BEST_IMAGINARY_FRIEND) == xi.questStatus.QUEST_ACCEPTED and\n            not player:hasStatusEffect(xi.effect.IONIS)\n        then\n            -- Progresses Quest: 'A Pioneers Best (Imaginary) Friend'\n            player:startEvent(2523)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 2523 then\n        -- Progresses Quest: 'A Pioneers Best (Imaginary) Friend'\n        player:delStatusEffectsByFlag(xi.effectFlag.INFLUENCE, true)\n        player:addStatusEffect(xi.effect.IONIS, { duration = 9000, origin = player })\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Shipilolo.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Shipilolo.lua",["SHA256"]="65cfa240e2c263b2db432f98c1153ba6885406a16231cb5cb0dedcfc0adb5d4d",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Shipilolo\n--  Involved with Quests: 'A Certain Substitute Patrolman'\n--                        'Fertile Ground'\n--                        'The Old Man and the Harpoon'\n--                        'Wayward Waypoints'\n-- !pos 84 0 -60 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local fertileGround    = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.FERTILE_GROUND)\n\n    if player:getCurrentMission(xi.mission.log_id.SOA) >= xi.mission.id.soa.LIFE_ON_THE_FRONTIER then\n        if\n            player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.THE_OLD_MAN_AND_THE_HARPOON) == xi.questStatus.QUEST_ACCEPTED and\n            player:hasKeyItem(xi.keyItem.BROKEN_HARPOON)\n        then\n            -- Progresses Quest: 'The Old Man and the Harpoon'\n            player:startEvent(2543)\n        elseif\n            fertileGround == xi.questStatus.QUEST_ACCEPTED and\n            not player:hasKeyItem(xi.keyItem.BOTTLE_OF_FERTILIZER_X)\n        then\n            -- Progresses Quest: 'Fertile Ground'\n            player:startEvent(2850)\n        elseif\n            player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.WAYWARD_WAYPOINTS) == xi.questStatus.QUEST_ACCEPTED and\n            player:getCharVar('WW_Need_Shipilolo') > 0 and\n            not player:hasKeyItem(xi.keyItem.WAYPOINT_RECALIBRATION_KIT)\n        then\n            -- Progresses Quest: 'Wayward Waypoints'\n            player:startEvent(79)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 2543 then\n        -- Progresses Quest: 'The Old Man and the Harpoon'\n        player:delKeyItem(xi.keyItem.BROKEN_HARPOON)\n        npcUtil.giveKeyItem(player, xi.keyItem.EXTRAVAGANT_HARPOON)\n    elseif csid == 2850 then\n        -- Progresses Quest: 'Fertile Ground' TODO: Should this also give the player a message?\n        player:addKeyItem(xi.keyItem.BOTTLE_OF_FERTILIZER_X)\n    elseif csid == 79 then\n        player:addKeyItem(xi.keyItem.WAYPOINT_RECALIBRATION_KIT)\n        player:setCharVar('WW_Need_Shipilolo', 0)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Terwok.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Terwok.lua",["SHA256"]="1f4b833466b485075fc8eb29458182af2e34f183b0623ccf42a8f3a190fdfa03",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Terwok\n--  Involved With Quest: 'Order Up'\n-- !pos 127 4 -81 256\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local orderUp = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.ORDER_UP)\n    local orderTerwok = utils.mask.getBit(player:getCharVar('Order_Up_NPCs'), 7)\n\n    if orderUp == xi.questStatus.QUEST_ACCEPTED and not orderTerwok then\n        -- Progresses Quest: 'Order Up'\n        player:startEvent(67)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 67 then\n        -- Progresses Quest: 'Order Up'\n        player:setCharVar('Order_Up_NPCs', utils.mask.setBit(player:getCharVar('Order_Up_NPCs'), 7, true))\n    end\nend\n\nreturn entity\n"},["scripts/zones/Western_Adoulin/npcs/Westerly_Breeze.lua"]={["Path"]="scripts/zones/Western_Adoulin/npcs/Westerly_Breeze.lua",["SHA256"]="92972e54a72f5736167f5a63e4a6f82230c72bed126edeeb232c14fa7a0942a8",["Text"]="-----------------------------------\n-- Area: Western Adoulin\n--  NPC: Westerly Breeze\n-- !pos 62 32 123 256\n-----------------------------------\nlocal ID = zones[xi.zone.WESTERN_ADOULIN]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local amqtr = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.ALWAYS_MORE_QUOTH_THE_RAVENOUS)\n\n    if trade:getItemCount() == 1 and trade:getGil() == 0 then\n        local item = trade:getItem(0)\n        if not item then\n            return\n        end\n\n        local itemId = item:getID()\n        local ahCategory = item:getAHCat()\n\n        if\n            ahCategory >= xi.itemAHCategory.MEAT_EGGS and\n            ahCategory <= xi.itemAHCategory.SWEETS\n        then\n            -- We traded him a food item\n            if\n                player:getCharVar('ATWTTB_Can_Trade_Gruel') == 1 and\n                (itemId == 4489 or itemId == 4534)\n            then\n                if itemId == 4489 then\n                    -- Trading him Vegetable Gruel after completing Quest: 'All The Way To The Bank'\n                    player:startEvent(5068)\n                elseif itemId == 4534 then\n                    -- Trading him Medicinal Gruel after completing Quest: 'All The Way To The Bank'\n                    player:startEvent(5068, 1)\n                end\n            end\n        elseif ahCategory == 58 then\n            if amqtr == xi.questStatus.QUEST_ACCEPTED then\n                if itemId == 4541 then\n                    -- We gave him another Goblin Drink.\n                    -- Special event where he refuses it.\n                    player:startEvent(3013)\n                else\n                    -- Special event where he drinks a non-goblin drink.\n                    player:startEvent(3014)\n                end\n            end\n        else\n            if itemId == 4234 and amqtr == xi.questStatus.QUEST_ACCEPTED then\n                -- We gave him Cursed Beverage.\n                -- Finishes Quest: 'Always More Quoth the Ravenous'\n                player:startEvent(3012)\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local amqtr = player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.ALWAYS_MORE_QUOTH_THE_RAVENOUS)\n\n    if\n        player:getFameLevel(xi.fameArea.ADOULIN) >= 2 and\n        not player:needToZone() and VanadielUniqueDay() > player:getCharVar('Westerly_Breeze_Wait')\n    then\n        if\n            amqtr ~= xi.questStatus.QUEST_COMPLETED and\n            player:getFameLevel(xi.fameArea.ADOULIN) >= 3\n        then\n            if amqtr == xi.questStatus.QUEST_AVAILABLE then\n                -- Starts Quest: 'Always More Quoth the Ravenous'\n                player:startEvent(3010)\n            else\n                -- Reminder for Quest: 'Always More Quoth the Ravenous'\n                player:startEvent(3011)\n            end\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 3010 then\n        -- Starting Quest: 'Always More Quoth the Ravenous'\n        player:addQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.ALWAYS_MORE_QUOTH_THE_RAVENOUS)\n    elseif csid == 3012 then\n        -- Finishing Quest: 'Always More Quoth The Ravenous'\n        player:tradeComplete()\n        player:completeQuest(xi.questLog.ADOULIN, xi.quest.id.adoulin.ALWAYS_MORE_QUOTH_THE_RAVENOUS)\n        player:addExp(1500 * xi.settings.main.EXP_RATE)\n        player:addCurrency('bayld', 1000 * xi.settings.main.BAYLD_RATE)\n        player:messageSpecial(ID.text.BAYLD_OBTAINED, 1000 * xi.settings.main.BAYLD_RATE)\n\n        -- TODO: Verify fame value added\n        player:addFame(xi.fameArea.ADOULIN, 30)\n        player:setCharVar('Westerly_Breeze_Wait', 0)\n    elseif csid == 3014 then\n        -- Consuming wrong food item given to him during his quests\n        player:tradeComplete()\n    elseif csid == 5068 then\n        -- Trading him gruel after Quest: 'All The Way To The Bank'\n        player:tradeComplete()\n        local gilObtained = 19716\n        if option == 1 then\n            gilObtained = 39432\n        end\n\n        npcUtil.giveCurrency(player, 'gil', gilObtained)\n        player:setCharVar('ATWTTB_Can_Trade_Gruel', 0)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/Ambrosius.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/Ambrosius.lua",["SHA256"]="343fc0bc67f79f36540fe09fca764d30c16658b6887ace51f6483d2ee05b55fb",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n--  NPC: Ambrosius\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local postman = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_POSTMAN_ALWAYS_KOS_TWICE)\n\n    if postman == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(48)\n    elseif postman == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(49)\n    elseif postman == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(56)\n    end\nend\n\nentity.onTrade = function(player, npc, trade)\n    local postman = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_POSTMAN_ALWAYS_KOS_TWICE)\n\n    if postman ~= xi.questStatus.QUEST_AVAILABLE then\n        local reward = 0\n\n        -- TODO: Table this on converting to Interaction\n        if trade:hasItemQty(xi.item.TORN_EPISTLE, 1) then\n            reward = reward + 1\n        end\n\n        if trade:hasItemQty(xi.item.MUDDY_BAR_TAB, 1) then\n            reward = reward + 1\n        end\n\n        if trade:hasItemQty(xi.item.ODD_POSTCARD, 1) then\n            reward = reward + 1\n        end\n\n        if trade:hasItemQty(xi.item.DAMP_ENVELOPE, 1) then\n            reward = reward + 1\n        end\n\n        if trade:getItemCount() == reward then\n            if reward == 1 then\n                if postman == xi.questStatus.QUEST_ACCEPTED then\n                    player:startEvent(52, xi.settings.main.GIL_RATE * 50)\n                elseif postman == xi.questStatus.QUEST_COMPLETED then\n                    player:startEvent(57, xi.settings.main.GIL_RATE * 50)\n                end\n            elseif reward == 2 then\n                if postman == xi.questStatus.QUEST_ACCEPTED then\n                    player:startEvent(53, xi.settings.main.GIL_RATE * 150, 2)\n                elseif postman == xi.questStatus.QUEST_COMPLETED then\n                    player:startEvent(58, xi.settings.main.GIL_RATE * 150, 2)\n                end\n            elseif reward == 3 then\n                if postman == xi.questStatus.QUEST_ACCEPTED then\n                    player:startEvent(54, xi.settings.main.GIL_RATE * 250, 3)\n                elseif postman == xi.questStatus.QUEST_COMPLETED then\n                    player:startEvent(59, xi.settings.main.GIL_RATE * 250, 3)\n                end\n            elseif reward == 4 then\n                if postman == xi.questStatus.QUEST_ACCEPTED then\n                    player:startEvent(55, xi.settings.main.GIL_RATE * 500, 4)\n                elseif postman == xi.questStatus.QUEST_COMPLETED then\n                    player:startEvent(60, xi.settings.main.GIL_RATE * 500, 4)\n                end\n            end\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 48 and option == 0 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_POSTMAN_ALWAYS_KOS_TWICE)\n    elseif csid == 52 then\n        player:tradeComplete()\n        player:addGil(xi.settings.main.GIL_RATE * 50)\n        player:addFame(xi.fameArea.WINDURST, 10)\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_POSTMAN_ALWAYS_KOS_TWICE)\n    elseif csid == 53 then\n        player:tradeComplete()\n        player:addGil(xi.settings.main.GIL_RATE * 150)\n        player:addFame(xi.fameArea.WINDURST, 10)\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_POSTMAN_ALWAYS_KOS_TWICE)\n    elseif csid == 54 then\n        player:tradeComplete()\n        player:addGil(xi.settings.main.GIL_RATE * 250)\n        player:addFame(xi.fameArea.WINDURST, 10)\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_POSTMAN_ALWAYS_KOS_TWICE)\n    elseif csid == 55 then\n        player:tradeComplete()\n        player:addGil(xi.settings.main.GIL_RATE * 500)\n        player:addFame(xi.fameArea.WINDURST, 10)\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_POSTMAN_ALWAYS_KOS_TWICE)\n    elseif csid == 57 then\n        player:tradeComplete()\n        player:addGil(xi.settings.main.GIL_RATE * 50)\n        player:addFame(xi.fameArea.WINDURST, 10)\n    elseif csid == 58 then\n        player:tradeComplete()\n        player:addGil(xi.settings.main.GIL_RATE * 150)\n        player:addFame(xi.fameArea.WINDURST, 10)\n    elseif csid == 59 then\n        player:tradeComplete()\n        player:addGil(xi.settings.main.GIL_RATE * 250)\n        player:addFame(xi.fameArea.WINDURST, 10)\n    elseif csid == 60 then\n        player:tradeComplete()\n        player:addGil(xi.settings.main.GIL_RATE * 500)\n        player:addFame(xi.fameArea.WINDURST, 10)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/Hiwon-Biwon.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/Hiwon-Biwon.lua",["SHA256"]="d2b861fbe21a9dcaecde6909ecb2d21e5142a0897392af89bbb319d0b2390436",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n--  NPC: Hiwon-Biwon\n-- Involved In Quest: Making Headlines, Curses, Foiled...Again!?\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local makingHeadlines = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_HEADLINES)\n    local cursesFoiledAgain1 = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CURSES_FOILED_AGAIN_1)\n\n    -- Making Headlines\n    if makingHeadlines == xi.questStatus.QUEST_ACCEPTED then\n        -- bitmask of progress: 0 = Kyume-Romeh, 1 = Yuyuju, 2 = Hiwom-Gomoi, 3 = Umumu, 4 = Mahogany Door\n        local prog = player:getCharVar('QuestMakingHeadlines_var')\n\n        if not utils.mask.getBit(prog, 2) then\n            if cursesFoiledAgain1 == xi.questStatus.QUEST_ACCEPTED then\n                if math.randomInt(1, 100) <= 50 then\n                    player:startEvent(283) -- Give scoop while sick\n                else\n                    player:startEvent(284) -- Give scoop while sick\n                end\n            else\n                player:startEvent(281) -- Give scoop\n            end\n        else\n            player:startEvent(282) -- \"Getting back to the maater at hand-wand...\"\n        end\n\n    -- default dialog\n    else\n        local rand = math.randomInt(1, 5)\n\n        if rand == 1 then\n            player:startEvent(305)\n        elseif rand == 2 then\n            player:startEvent(306)\n        elseif rand == 3 then\n            player:startEvent(168)\n        elseif rand == 4 then\n            player:startEvent(170)\n        elseif rand == 5 then\n            player:startEvent(169)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- Making Headlines\n    if csid == 281 or csid == 283 or csid == 284 then\n        npcUtil.giveKeyItem(player, xi.keyItem.WINDURST_WALLS_SCOOP)\n        player:setCharVar('QuestMakingHeadlines_var', utils.mask.setBit(player:getCharVar('QuestMakingHeadlines_var'), 2, true))\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/Kalupa-Tawalupa.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/Kalupa-Tawalupa.lua",["SHA256"]="d421167574ae7f008cef8dc68a837d497347afbec043cff2f8951d8cc07f992c",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n--  Location: X:-90  Y:-9  Z:109\n--  NPC: Kalupa-Tawalupa\n--  Involved in Quest: To Bee or Not to Bee?\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local toBee = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TO_BEE_OR_NOT_TO_BEE)\n    local toBeeOrNotStatus = player:getCharVar('ToBeeOrNot_var')\n\n    if toBeeOrNotStatus == 10 then\n        player:startEvent(66) -- During Too Bee quest before honey given to Zayhi: 'are you alright sir'\n    elseif toBee == xi.questStatus.QUEST_ACCEPTED and toBeeOrNotStatus > 0 then\n        player:startEvent(72) -- During Too Bee quest after some honey was given to Zayhi: 'hey did that honey help you just now?'\n    elseif toBee == xi.questStatus.QUEST_COMPLETED and player:needToZone() then\n        player:startEvent(77) -- After Too Bee quest but before zone: 'well I guess a tooth ache is to be expected'\n    else\n        player:startEvent(298) -- Normal conversation\n    end\nend\n\n-- CS/Event ID List for NPC\n-- *CS 443 - player:startEvent(443) -- Long Star Sybil CS\n-- CS 298 - player:startEvent(298) -- Normal conversation\n-- *CS 64 - player:startEvent(64) -- Zayhi Coughing\n-- CS 66 - player:startEvent(66) -- During Too Bee quest before honey given to Zayhi: \"are you alright sir\"\n-- CS 72 - player:startEvent(72) -- During Too Bee quest after some honey was given to Zayhi: \"hey did that honey help you just now?\"\n-- *CS 75 - player:startEvent(75) -- Combo CS: During Too Bee quest, kicked off from Zayhi\n-- CS 77 - player:startEvent(77) -- After Too Bee quest but before zone: \"well I guess a tooth ache is to be expected\"\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/Koru-Moru.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/Koru-Moru.lua",["SHA256"]="2e07483e3920f2aa7a6d21f186f91c0d2b46e77aa308ff4927aafda40b528e92",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n--  NPC: Koru-Moru\n-- Starts & Ends Quest: Star Struck\n-- Involved in Quest: Making the Grade, Riding on the Clouds\n-- !pos -120 -6 124 239\n-----------------------------------\nlocal ID = zones[xi.zone.WINDURST_WALLS]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local count = trade:getItemCount()\n\n    if\n        trade:hasItemQty(xi.item.SQUARE_OF_SILK_CLOTH, 1) and\n        count == 1 and\n        trade:getGil() == 0\n    then\n        if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ROOT_OF_THE_PROBLEM) == xi.questStatus.QUEST_ACCEPTED then\n            player:startEvent(349)\n            player:tradeComplete()\n            player:setCharVar('rootProblem', 2)\n        end\n    elseif\n        trade:hasItemQty(xi.item.ASTRAGALOS, 4) and\n        count == 4 and\n        trade:getGil() == 0\n    then\n        if\n            player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION) == xi.questStatus.QUEST_ACCEPTED and\n            player:getCharVar('ClassReunionProgress') == 2\n        then\n            player:startEvent(407) -- now Koru remembers something that you need to inquire his former students.\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local rootProblem = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ROOT_OF_THE_PROBLEM)\n    local thePuppetMaster = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_PUPPET_MASTER)\n    local classReunion = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION)\n    local classReunionProgress = player:getCharVar('ClassReunionProgress')\n    local talk1 = player:getCharVar('ClassReunion_TalkedToFupepe')\n    local talk2 = player:getCharVar('ClassReunion_TalkedToFurakku')\n    local carbuncleDebacle = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CARBUNCLE_DEBACLE)\n    local carbuncleDebacleProgress = player:getCharVar('CarbuncleDebacleProgress')\n\n    -----------------------------------\n    -- Carbuncle Debacle\n    if\n        carbuncleDebacle == xi.questStatus.QUEST_ACCEPTED and\n        carbuncleDebacleProgress == 1 or\n        carbuncleDebacleProgress == 2\n    then\n        player:startEvent(416) -- go and see Ripapa\n    elseif\n        carbuncleDebacle == xi.questStatus.QUEST_ACCEPTED and\n        carbuncleDebacleProgress == 4\n    then\n        player:startEvent(417) -- now go and see Agado-Pugado\n    elseif\n        carbuncleDebacle == xi.questStatus.QUEST_ACCEPTED and\n        carbuncleDebacleProgress == 5\n    then\n        player:startEvent(418) -- Uran-Mafran must be stopped\n    elseif\n        carbuncleDebacle == xi.questStatus.QUEST_ACCEPTED and\n        carbuncleDebacleProgress == 7\n    then\n        player:startEvent(419) -- ending cs\n    elseif\n        thePuppetMaster == xi.questStatus.QUEST_COMPLETED and\n        classReunion == xi.questStatus.QUEST_COMPLETED and\n        carbuncleDebacle == xi.questStatus.QUEST_COMPLETED\n    then\n        player:startEvent(420) -- new cs after all 3 SMN AFs done\n    -----------------------------------\n    -- Class Reunion\n    elseif\n        classReunion == xi.questStatus.QUEST_ACCEPTED and\n        classReunionProgress == 1\n    then\n        player:startEvent(412, 0, 450, xi.item.ASTRAGALOS, 0, 0, 0, 0, 0) -- bring Koru 4 astragaloi\n    elseif\n        classReunion == xi.questStatus.QUEST_ACCEPTED and\n        classReunionProgress == 2\n    then\n        player:startEvent(414, 0, 0, xi.item.ASTRAGALOS, 0, 0, 0, 0, 0) -- reminder to bring 4 astragaloi\n    elseif\n        classReunion == xi.questStatus.QUEST_ACCEPTED and\n        classReunionProgress >= 3 and\n        (talk1 ~= 1 or talk2 ~= 1)\n    then\n        player:startEvent(408) -- reminder to visit the students\n    elseif\n        classReunion == xi.questStatus.QUEST_ACCEPTED and\n        classReunionProgress == 6 and\n        talk1 == 1 and\n        talk2 == 1\n    then\n            player:startEvent(410) -- ending cs\n    elseif\n        thePuppetMaster == xi.questStatus.QUEST_COMPLETED and\n        classReunion == xi.questStatus.QUEST_COMPLETED\n    then\n        player:startEvent(411) -- new cs after completed AF2\n    -----------------------------------\n    elseif\n        rootProblem == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('rootProblem') == 1\n    then\n        player:startEvent(348, 0, xi.item.SQUARE_OF_SILK_CLOTH)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 412 then\n        player:delKeyItem(xi.keyItem.CARBUNCLES_TEAR)\n        player:setCharVar('ClassReunionProgress', 2)\n    elseif csid == 407 then\n        player:tradeComplete()\n        player:setCharVar('ClassReunionProgress', 3)\n    elseif csid == 410 then\n        if player:getFreeSlotsCount() ~= 0 then\n            player:addItem(xi.item.EVOKERS_SPATS)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.EVOKERS_SPATS)\n            player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION)\n            player:setCharVar('ClassReunionProgress', 0)\n            player:setCharVar('ClassReunion_TalkedToFurakku', 0)\n            player:setCharVar('ClassReunion_TalkedToFupepe', 0)\n            player:needToZone(true)\n            player:addFame(xi.fameArea.WINDURST, 20)\n        else\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.EVOKERS_SPATS)\n        end\n    elseif csid == 416 then\n        player:setCharVar('CarbuncleDebacleProgress', 2)\n    elseif csid == 417 then\n        player:setCharVar('CarbuncleDebacleProgress', 5)\n        npcUtil.giveKeyItem(player, xi.keyItem.DAZE_BREAKER_CHARM)\n    elseif csid == 419 then\n        if player:getFreeSlotsCount() ~= 0 then\n            player:addItem(xi.item.EVOKERS_HORN) -- Evoker's Horn\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.EVOKERS_HORN)\n            player:addTitle(xi.title.PARAGON_OF_SUMMONER_EXCELLENCE)\n            player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CARBUNCLE_DEBACLE)\n            player:addFame(xi.fameArea.WINDURST, 20)\n            player:setCharVar('CarbuncleDebacleProgress', 0)\n            player:needToZone(true)\n        else\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.EVOKERS_HORN)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/Orudoba-Sondeba.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/Orudoba-Sondeba.lua",["SHA256"]="fc305f6cd4196c8c415be629173f397b2780f3eccbeca8ce2397c5a888553b9a",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n--  NPC: Orudoba-Sondeba\n-- !pos 70.086 -3.503 -69.939 239\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_POSTMAN_ALWAYS_KOS_TWICE) == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(51)\n    else\n        player:startEvent(43)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/Raamimi.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/Raamimi.lua",["SHA256"]="2dea38e1042547ea1d411cb8c01333c389a8954738ac2acd9aac3626baa000c6",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n--  Location: X:-81  Y:-9  Z:103\n--  NPC: Raamimi\n--  Involved in Quest: To Bee or Not to Bee?\n-----------------------------------\nlocal ID = zones[xi.zone.WINDURST_WALLS]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local toBee = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TO_BEE_OR_NOT_TO_BEE)\n    local toBeeOrNotStatus = player:getCharVar('ToBeeOrNot_var')\n\n    if toBeeOrNotStatus == 10 and toBee == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(67) -- Quest Started - He gives you honey\n    elseif toBee == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(68) -- After honey is given to player...... but before 5th hondy is given to Zayhi\n    elseif toBee == xi.questStatus.QUEST_COMPLETED and toBeeOrNotStatus == 5 then\n        player:startEvent(80) -- Quest Finish - Gives Mulsum\n    elseif\n        toBee == xi.questStatus.QUEST_COMPLETED and\n        toBeeOrNotStatus == 0 and\n        player:needToZone()\n    then\n        player:startEvent(79) -- After Quest but before zoning \"it's certainly gotten quiet around here...\"\n    else\n        player:startEvent(296)\n    end\nend\n\n-- Event ID List for NPC\n--  player:startEvent(296) -- Standard Conversation\n--  player:startEvent(67) -- Quest is kicked off already, he gives you honey\n-- player:startEvent(68) -- After honey is given to player...... before given to Zayhi????\n--  player:startEvent(80) -- Quest Finish - Gives Mulsum\n--  player:startEvent(79) -- After Quest but before zoning: \"it's certainly gotten quiet around here...\"\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 67 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.POT_OF_HONEY) -- Cannot give Honey because player Inventory is full\n        else\n            player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.TO_BEE_OR_NOT_TO_BEE)\n            player:addItem(xi.item.POT_OF_HONEY)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.POT_OF_HONEY) -- Gives player Honey x1\n        end\n    elseif csid == 80 then -- After Honey#5: ToBee quest Finish (tooth hurts from all the Honey)\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, 4156) -- Cannot give Mulsum because player Inventory is full\n        else\n            player:setCharVar('ToBeeOrNot_var', 0)\n            player:addItem(xi.item.BOTTLE_OF_MULSUM, 3) -- Mulsum x3\n            player:messageSpecial(ID.text.ITEMS_OBTAINED, xi.item.BOTTLE_OF_MULSUM, 3)\n            player:needToZone(true)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/Rutango-Botango.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/Rutango-Botango.lua",["SHA256"]="040214e2eb788aadcdf5b88bfd0170c4fdf88dfee385c322b14b9e9294ba7d08",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n--  Location: X:-92  Y:-9  Z:107\n--  NPC: Rutango-Botango\n--  Involved in Quest: To Bee or Not to Bee?\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local toBee = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TO_BEE_OR_NOT_TO_BEE)\n    local toBeeOrNotStatus = player:getCharVar('ToBeeOrNot_var')\n\n    if toBeeOrNotStatus == 10 then\n        player:startEvent(65) -- During Too Bee quest before honey given to Zayhi:  'Oh Crumb...lost his voice'\n    elseif toBee == xi.questStatus.QUEST_ACCEPTED and toBeeOrNotStatus > 0 then\n        player:startEvent(71) -- During Too Bee quest after some honey was given to Zayhi: 'lap up more honey'\n    elseif toBee == xi.questStatus.QUEST_COMPLETED and player:needToZone() then\n        player:startEvent(76) -- After Too Bee quest but before zone: 'master let me speak for you'\n    else\n        player:startEvent(297) -- Standard Conversation\n    end\nend\n\n-- CS/Event ID List for NPC\n-- *Rutango-Botango    CS 443 - player:startEvent(443) -- Long Star Sybil CS\n-- Rutango-Botango    CS 297 - player:startEvent(297) -- Standard Conversation\n-- *Rutango-Botango    CS 64 - player:startEvent(64) -- Zayhi Coughing\n-- Rutango-Botango    CS 65 - player:startEvent(65) -- During Too Bee quest before honey given to Zayhi:  \"Oh Crumb...lost his voice\"\n-- Rutango-Botango    CS 71 - player:startEvent(71) -- During Too Bee quest after some honey was given to Zayhi: \"lap up more honey\"\n-- *Rutango-Botango    CS 75 - player:startEvent(75) -- Combo CS: During Too Bee quest, kicked off from Zayhi\n-- Rutango-Botango    CS 76 - player:startEvent(76) -- After Too Bee quest but before zone: \"master let me speak for you\"\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/Shantotto.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/Shantotto.lua",["SHA256"]="ad1c24e15bc16c17e7c4ce903c0f299b72d32d830b0867ba36746c6329ddeb58",["Text"]="-----------------------------------\n-- Area: Windurst Walls (239)\n--  NPC: Shantotto\n-- !pos 122 -2 112 239\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('ClassReunionProgress') == 3\n    then\n        player:startEvent(409) -- she mentions that Sunny-Pabonny left for San d'Oria\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 409 then\n        player:setCharVar('ClassReunionProgress', 4)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/Tsuaora-Tsuora.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/Tsuaora-Tsuora.lua",["SHA256"]="26a0c41a7e02442b5efeca378322b43bec3d151b2945c41889c6697c9e5d8ea9",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n--  NPC: Tsuaora-Tsuora\n-- !pos 71.489 -3.418 -67.809 239\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_POSTMAN_ALWAYS_KOS_TWICE) == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(50)\n    else\n        player:startEvent(42)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/Yoran-Oran.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/Yoran-Oran.lua",["SHA256"]="4ca4f0a467fa631230910e1409f37ac91beb0b573741d51d64bda84c5e83e91f",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n--  NPC: Yoran-Oran\n-- !pos -109.987 -14 203.338 239\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MANDRAGORA_MAD) ~= xi.questStatus.QUEST_AVAILABLE then\n        if npcUtil.tradeHas(trade, xi.item.CORNETTE, true) then\n            player:startEvent(251, xi.settings.main.GIL_RATE * 200)\n        elseif npcUtil.tradeHas(trade, xi.item.PINCH_OF_YUHTUNGA_SULFUR, true) then\n            player:startEvent(252, xi.settings.main.GIL_RATE * 250)\n        elseif npcUtil.tradeHas(trade, xi.item.THREE_LEAF_MANDRAGORA_BUD, true) then\n            player:startEvent(253, xi.settings.main.GIL_RATE * 1200)\n        elseif npcUtil.tradeHas(trade, xi.item.FOUR_LEAF_MANDRAGORA_BUD, true) then\n            player:startEvent(254, xi.settings.main.GIL_RATE * 120)\n        elseif npcUtil.tradeHas(trade, xi.item.SNOBBY_LETTER, true) then\n            player:startEvent(255, xi.settings.main.GIL_RATE * 5500)\n        else\n            player:startEvent(250)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local mandragoraMad = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MANDRAGORA_MAD)\n\n    if mandragoraMad == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(249)\n    elseif mandragoraMad == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(256)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 249 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.MANDRAGORA_MAD)\n\n    -- TODO: This can easily be handled as a table, keyed by csid - 250 when in range\n    elseif csid == 251 then\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.MANDRAGORA_MAD, { fame = 10, fameArea = xi.fameArea.WINDURST })\n        player:addGil(xi.settings.main.GIL_RATE * 200)\n        player:confirmTrade()\n    elseif csid == 252 then\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.MANDRAGORA_MAD, { fame = 10, fameArea = xi.fameArea.WINDURST })\n        player:addGil(xi.settings.main.GIL_RATE * 250)\n        player:confirmTrade()\n    elseif csid == 253 then\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.MANDRAGORA_MAD, { fame = 22, fameArea = xi.fameArea.WINDURST })\n        player:addGil(xi.settings.main.GIL_RATE * 1200)\n        player:confirmTrade()\n    elseif csid == 254 then\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.MANDRAGORA_MAD, { fame = 10, fameArea = xi.fameArea.WINDURST })\n        player:addGil(xi.settings.main.GIL_RATE * 120)\n        player:confirmTrade()\n    elseif csid == 255 then\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.MANDRAGORA_MAD, { fame = 36, fameArea = xi.fameArea.WINDURST })\n        player:addGil(xi.settings.main.GIL_RATE * 5500)\n        player:confirmTrade()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/Zayhi-Bauhi.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/Zayhi-Bauhi.lua",["SHA256"]="58341f3a383e8b7c057d19b13d2fd702ad314828bd91764285b76e0cba73ef59",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n--  Location: X:-91  Y:-9  Z:109\n--  NPC: Zayhi-Bauhi\n--  Starts and Finishes Quest: To Bee or Not to Bee?\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TO_BEE_OR_NOT_TO_BEE) == xi.questStatus.QUEST_ACCEPTED then\n        if trade:hasItemQty(xi.item.POT_OF_HONEY, 1) and trade:getItemCount() == 1 then\n            local toBeeOrNotStatus = player:getCharVar('ToBeeOrNot_var')\n            if toBeeOrNotStatus == 10 then\n                player:startEvent(69) -- After Honey#1: Clearing throat\n            elseif toBeeOrNotStatus == 1 then\n                player:startEvent(70) -- After Honey#2: Tries to speak again... coughs\n            elseif toBeeOrNotStatus == 2 then\n                player:startEvent(73) -- After Honey#3: Tries to speak again... coughs..asked for more Honey\n            elseif toBeeOrNotStatus == 3 then\n                player:startEvent(74) -- After Honey#4: Feels like its getting a lot better but there is still iritaion\n            elseif toBeeOrNotStatus == 4 then\n                player:startEvent(75) -- After Honey#5: ToBee quest Finish (tooth hurts from all the Honey\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local toBee = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TO_BEE_OR_NOT_TO_BEE)\n    local postmanKOsTwice = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_POSTMAN_ALWAYS_KOS_TWICE)\n    local toBeeOrNotStatus = player:getCharVar('ToBeeOrNot_var')\n\n    if\n        (player:getFameLevel(xi.fameArea.WINDURST) >= 2 and postmanKOsTwice == xi.questStatus.QUEST_COMPLETED and toBee == xi.questStatus.QUEST_AVAILABLE) or\n        (toBee == xi.questStatus.QUEST_ACCEPTED and toBeeOrNotStatus == 10)\n    then\n        player:startEvent(64)   -- Just Before Quest Start 'Too Bee or Not Too Be' (Speech given with lots of coughing)\n    elseif toBee == xi.questStatus.QUEST_ACCEPTED then\n        if toBeeOrNotStatus == 1 then\n            player:startEvent(69) -- After Honey#1: Clearing throat\n        elseif toBeeOrNotStatus == 2 then\n            player:startEvent(70) -- After Honey#2: Tries to speak again... coughs\n        elseif toBeeOrNotStatus == 3 then\n            player:startEvent(73) -- After Honey#3: Tries to speak again... coughs..asked for more Honey\n        elseif toBeeOrNotStatus == 4 then\n            player:startEvent(74) -- After Honey#4: Feels like its getting a lot better but there is still iritaion\n        end\n    elseif toBee == xi.questStatus.QUEST_COMPLETED and player:needToZone() then\n        player:startEvent(78) -- ToBee After Quest Finish but before zone (tooth still hurts)\n    else\n        player:startEvent(299) -- Normal speech\n    end\nend\n\n--        Event ID List for NPC\n--      player:startEvent(299) -- Normal speach\n--      player:startEvent(61) -- Normal speach\n--      player:startEvent(64) -- Start quest \"Too Bee or Not Too Be\" (Speech given with lots of coughing)\n--      player:startEvent(69) -- After Honey#1: Clearing throat\n--      player:startEvent(70) -- After Honey#2: Tries to speak again... coughs\n--      player:startEvent(73) -- After Honey#3: Tries to speak again... coughs..asked for more Honey\n--      player:startEvent(74) -- After Honey#4: Feels like its getting a lot better but there is still iritaion\n--      player:startEvent(75) -- After Honey#5: ToBee quest Finish (tooth hurts from all the Honey)\n--      player:startEvent(78) -- ToBee After Quest Finish but before zone (tooth still hurts)\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 64 then\n        player:setCharVar('ToBeeOrNot_var', 10)\n    elseif csid == 69 then -- After Honey#1: Clearing throat\n        player:tradeComplete()\n        player:setCharVar('ToBeeOrNot_var', 1)\n    elseif csid == 70 then -- After Honey#2: Tries to speak again... coughs\n        player:tradeComplete()\n        player:setCharVar('ToBeeOrNot_var', 2)\n    elseif csid == 73 then -- After Honey#3: Tries to speak again... coughs..asked for more Honey\n        player:tradeComplete()\n        player:setCharVar('ToBeeOrNot_var', 3)\n    elseif csid == 74 then -- After Honey#4: Feels like its getting a lot better but there is still iritaion\n        player:tradeComplete()\n        player:setCharVar('ToBeeOrNot_var', 4)\n    elseif csid == 75 then -- After Honey#5: ToBee quest Finish (tooth hurts from all the Honey)\n        player:tradeComplete()\n        player:setCharVar('ToBeeOrNot_var', 5)\n        player:addFame(xi.fameArea.WINDURST, 20)\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.TO_BEE_OR_NOT_TO_BEE)\n        player:needToZone(true)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Walls/npcs/_6n2.lua"]={["Path"]="scripts/zones/Windurst_Walls/npcs/_6n2.lua",["SHA256"]="573c5f96d79063271b3c825ee540268b23538fee7278a9ded1120effd6169d97",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n-- Door: House of the Hero\n-- Involved In Quest: Know One's Onions, Onion Rings, The Puppet Master, Class Reunion\n-- !pos -26 -13 260 239\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local thePuppetMaster  = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_PUPPET_MASTER)\n    local classReunion     = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION)\n    local carbuncleDebacle = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CARBUNCLE_DEBACLE)\n\n    -- CLASS REUNION\n    if\n        thePuppetMaster == xi.questStatus.QUEST_COMPLETED and\n        classReunion == xi.questStatus.QUEST_AVAILABLE and\n        player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL and\n        player:getMainJob() == xi.job.SMN and\n        not player:needToZone()\n    then\n        player:startEvent(413)\n\n    -- CARBUNCLE DEBACLE\n    elseif\n        thePuppetMaster == xi.questStatus.QUEST_COMPLETED and\n        classReunion == xi.questStatus.QUEST_COMPLETED and\n        carbuncleDebacle == xi.questStatus.QUEST_AVAILABLE and\n        player:getMainLvl() >= xi.settings.main.AF3_QUEST_LEVEL and\n        player:getMainJob() == xi.job.SMN and\n        not player:needToZone()\n    then\n        player:startEvent(415)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- CLASS REUNION\n    if csid == 413 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION)\n        npcUtil.giveKeyItem(player, xi.keyItem.CARBUNCLES_TEAR)\n        player:setCharVar('ClassReunionProgress', 1)\n\n    -- CARBUNCLE DEBACLE\n    elseif csid == 415 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CARBUNCLE_DEBACLE)\n        player:setCharVar('CarbuncleDebacleProgress', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters/npcs/Baren-Moren.lua"]={["Path"]="scripts/zones/Windurst_Waters/npcs/Baren-Moren.lua",["SHA256"]="5125420b25a8ebe771c2b79b0e954c5f84d311cd2c8cb6e878dcbc8b84c6cfb7",["Text"]="-----------------------------------\n-- Area: Windurst Waters\n--  NPC: Baren-Moren\n-- Starts and Finishes Quest: Hat in Hand\n-- !pos -66 -3 -148 238\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local aFeatherInOnesCap = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.A_FEATHER_IN_ONES_CAP)\n\n    if\n        (aFeatherInOnesCap == xi.questStatus.QUEST_ACCEPTED or\n        player:getCharVar('QuestFeatherInOnesCap_var') == 1) and\n        npcUtil.tradeHas(trade, { { 842, 3 } })\n    then\n        player:startEvent(79, 1500) -- Quest Turn In\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local hatInHand         = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.HAT_IN_HAND)\n    local aFeatherInOnesCap = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.A_FEATHER_IN_ONES_CAP)\n    local pfame             = player:getFameLevel(xi.fameArea.WINDURST)\n\n    if\n        hatInHand == xi.questStatus.QUEST_AVAILABLE and\n        player:getVar('Quest[2][23]Prog') == 0 -- Quest progress in \"All At Sea\" blocks \"Hat In Hand\" from starting\n    then\n        player:startEvent(48) -- Quest Offered\n    elseif player:hasKeyItem(xi.keyItem.NEW_MODEL_HAT) then\n        local count = player:getCharVar('QuestHatInHand_count')\n\n        if count >= 8 then\n            player:startEvent(52, 80) -- 80 = HAT + FULL REWARD = 8 NPCS\n            player:setLocalVar('hatRewardTier', 5)\n        elseif count >= 6 then\n            player:startEvent(52, 50) -- 50 = HAT + GOOD REWARD >= 6-7 NPCS\n            player:setLocalVar('hatRewardTier', 4)\n        elseif count >= 4 then\n            player:startEvent(52, 30) -- 30 = PARTIAL REWARD >= 4-5 NPCS\n            player:setLocalVar('hatRewardTier', 3)\n        elseif count >= 2 then\n            player:startEvent(52, 20) -- 20 = POOR REWARD >= 2-3 NPCS\n            player:setLocalVar('hatRewardTier', 2)\n        else\n            player:startEvent(52) -- 0 = NO REWARD >= 0-1 NPCS\n            player:setLocalVar('hatRewardTier', 1)\n        end\n    elseif\n        hatInHand == xi.questStatus.QUEST_COMPLETED and\n        aFeatherInOnesCap == xi.questStatus.QUEST_AVAILABLE and\n        pfame >= 3 and\n        not player:needToZone()\n    then\n        player:startEvent(75, 0, 842) -- Quest 'Feather In One's Cap' offered\n    elseif\n        aFeatherInOnesCap == xi.questStatus.QUEST_ACCEPTED or\n        player:getCharVar('QuestFeatherInOnesCap_var') == 1\n    then\n        player:startEvent(78, 0, 842) -- Quest Objective Reminder\n    elseif\n        aFeatherInOnesCap == xi.questStatus.QUEST_COMPLETED and\n        not player:needToZone()\n    then\n        player:startEvent(75, 0, 842) -- Repeatable Quest 'A Feather In One's Cap' offered\n\n    -- default dialog\n    else\n        local rand = math.randomInt(1, 6)\n\n        if rand == 1 then\n            player:startEvent(42) -- Standard Conversation 1\n        elseif rand == 2 then\n            player:startEvent(44) -- Standard Conversation 2\n        elseif rand == 3 then\n            player:startEvent(45) -- Standard Conversation 3\n        elseif rand == 4 then\n            player:startEvent(46) -- Standard Conversation 4\n        elseif rand == 5 then\n            player:startEvent(47) -- Standard Conversation 5\n        elseif rand == 6 then\n            player:startEvent(1022) -- Standard Conversation 6\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    local aFeatherInOnesCap = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.A_FEATHER_IN_ONES_CAP)\n\n    if csid == 48 and option == 1 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.HAT_IN_HAND)\n        npcUtil.giveKeyItem(player, xi.keyItem.NEW_MODEL_HAT)\n    elseif csid == 52 and option >= 1 then\n        local rewardTier = player:getLocalVar('hatRewardTier')\n        local rewards = { fame = 10, fameArea = xi.fameArea.WINDURST, var = { 'QuestHatInHand_var', 'QuestHatInHand_count' } }\n\n        if rewardTier == 5 then\n            rewards.gil = 500\n            rewards.item = 12543\n        elseif rewardTier == 4 then\n            rewards.gil = 400\n            rewards.item = 12543\n        elseif rewardTier == 3 then\n            rewards.gil = 300\n        elseif rewardTier == 2 then\n            rewards.gil = 150\n        elseif rewardTier == 1 then\n            rewards.gil = 300\n        end\n\n        if npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.HAT_IN_HAND, rewards) then\n            player:delKeyItem(xi.keyItem.NEW_MODEL_HAT)\n            player:needToZone(true)\n        end\n    elseif csid == 75 and option == 1 then\n        if aFeatherInOnesCap == xi.questStatus.QUEST_AVAILABLE then\n            player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.A_FEATHER_IN_ONES_CAP)\n        elseif aFeatherInOnesCap == xi.questStatus.QUEST_COMPLETED then\n            player:setCharVar('QuestFeatherInOnesCap_var', 1)\n        end\n    elseif csid == 79 then\n        if aFeatherInOnesCap == xi.questStatus.QUEST_ACCEPTED then\n            npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.A_FEATHER_IN_ONES_CAP, { fame = 16, fameArea = xi.fameArea.WINDURST })\n        else\n            player:addFame(xi.fameArea.WINDURST, 16)\n            player:setCharVar('QuestFeatherInOnesCap_var', 0)\n        end\n\n        player:addGil(xi.settings.main.GIL_RATE * 1500)\n        player:confirmTrade()\n        player:needToZone(true)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters/npcs/Chamama.lua"]={["Path"]="scripts/zones/Windurst_Waters/npcs/Chamama.lua",["SHA256"]="4f218865db8a0169e84992e53c1892f08c02b1a344909d99841bef8d47bca214",["Text"]="-----------------------------------\n-- Area: Windurst Waters\n--  NPC: Chamama\n-- Involved In Quest: Inspector's Gadget\n-- Starts Quest: In a Pickle\n-----------------------------------\nlocal ID = zones[xi.zone.WINDURST_WATERS]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local inAPickle = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.IN_A_PICKLE)\n\n    if\n        (inAPickle == xi.questStatus.QUEST_ACCEPTED or inAPickle == xi.questStatus.QUEST_COMPLETED) and\n        trade:hasItemQty(xi.item.SMOOTH_STONE, 1) and\n        trade:getItemCount() == 1 and\n        trade:getGil() == 0\n    then\n        local rand = math.randomInt(1, 4)\n        if rand <= 2 then\n            if inAPickle == xi.questStatus.QUEST_ACCEPTED then\n                player:startEvent(659) -- IN A PICKLE: Quest Turn In (1st Time)\n            elseif inAPickle == xi.questStatus.QUEST_COMPLETED then\n                player:startEvent(662, 200)\n            end\n        elseif rand == 3 then\n            player:startEvent(657) -- IN A PICKLE: Too Light\n            player:tradeComplete()\n        elseif rand == 4 then\n            player:startEvent(658) -- IN A PICKLE: Too Small\n            player:tradeComplete()\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local inAPickle = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.IN_A_PICKLE)\n    local needToZone = player:needToZone()\n\n    if inAPickle == xi.questStatus.QUEST_AVAILABLE and not needToZone then\n        local rand = math.randomInt(1, 2)\n        if rand == 1 then\n            player:startEvent(654, 0, xi.item.RARAB_TAIL) -- IN A PICKLE + RARAB TAIL: Quest Begin\n        else\n            player:startEvent(651) -- Standard Conversation\n        end\n    elseif\n        inAPickle == xi.questStatus.QUEST_ACCEPTED or\n        player:getCharVar('QuestInAPickle_var') == 1\n    then\n        player:startEvent(655, 0, xi.item.RARAB_TAIL) -- IN A PICKLE + RARAB TAIL: Quest Objective Reminder\n    elseif inAPickle == xi.questStatus.QUEST_COMPLETED and needToZone then\n        player:startEvent(660) -- IN A PICKLE: After Quest\n    elseif\n        inAPickle == xi.questStatus.QUEST_COMPLETED and\n        not needToZone and\n        player:getCharVar('QuestInAPickle_var') ~= 1\n    then\n        local rand = math.randomInt(1, 2)\n        if rand == 1 then\n            player:startEvent(661) -- IN A PICKLE: Repeatable Quest Begin\n        else\n            player:startEvent(651) -- Standard Conversation\n        end\n    else\n        player:startEvent(651) -- Standard Conversation\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 654 and option == 1 then -- IN A PICKLE + RARAB TAIL: Quest Begin\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.IN_A_PICKLE)\n    elseif csid == 659 then -- IN A PICKLE: Quest Turn In (1st Time)\n        player:tradeComplete()\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.IN_A_PICKLE)\n        player:needToZone(true)\n        player:addItem(xi.item.BONE_HAIRPIN)\n        player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.BONE_HAIRPIN)\n        npcUtil.giveCurrency(player, 'gil', 200)\n        player:addFame(xi.fameArea.WINDURST, 10)\n    elseif csid == 661 and option == 1 then\n        player:setCharVar('QuestInAPickle_var', 1)\n    elseif csid == 662 then -- IN A PICKLE + 200 GIL: Repeatable Quest Turn In\n        player:tradeComplete()\n        player:needToZone(true)\n        player:addGil(xi.settings.main.GIL_RATE * 200)\n        player:addFame(xi.fameArea.WINDURST, 10)\n        player:setCharVar('QuestInAPickle_var', 0)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters/npcs/Fuepepe.lua"]={["Path"]="scripts/zones/Windurst_Waters/npcs/Fuepepe.lua",["SHA256"]="f434a5baca8cf52028137b8338ec77755a5602760806f02bc0d3074806760248",["Text"]="-----------------------------------\n-- Area: Windurst Waters\n--  NPC: Fuepepe\n-- Involved in Quest: Class Reunion\n-- !pos 161 -2 161 238\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local classReunion = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION)\n\n    -- CLASS REUNION\n    if\n        classReunion == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('ClassReunionProgress') >= 3 and\n        player:getCharVar('ClassReunion_TalkedToFupepe') ~= 1\n    then\n        player:startEvent(817) -- he tells you about Uran-Mafran\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 817 then\n        player:setCharVar('ClassReunion_TalkedToFupepe', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters/npcs/Furakku-Norakku.lua"]={["Path"]="scripts/zones/Windurst_Waters/npcs/Furakku-Norakku.lua",["SHA256"]="4484686ad819bfa69811b6d12f87ec03f363d87ad64ea28cac0358ce4c0a2d77",["Text"]="-----------------------------------\n-- Area: Windurst Waters\n--  NPC: Furakku-Norakku\n-- Involved in Quests: Early Bird Catches the Bookworm, Chasing Tales, Class Reunion\n-- !pos -19 -5 101 238\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local classReunion = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION)\n    local classReunionProgress = player:getCharVar('ClassReunionProgress')\n    local talk2 = player:getCharVar('ClassReunion_TalkedToFurakku')\n\n    -- Class Reunion\n    if classReunion == 1 and classReunionProgress >= 3 and talk2 ~= 1 then\n        player:startEvent(816) -- he tells you about Uran-Mafran\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 816 then\n        player:setCharVar('ClassReunion_TalkedToFurakku', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters/npcs/Kyume-Romeh.lua"]={["Path"]="scripts/zones/Windurst_Waters/npcs/Kyume-Romeh.lua",["SHA256"]="0559d4486d969c0f2715e7e8d3dc6e3700f57224d3d990e1b5d125095078666f",["Text"]="-----------------------------------\n-- Area: Windurst Waters\n--  NPC: Kyume-Romeh\n--  Involved In Quest: Making Headlines, Hat in Hand\n-- !pos -58 -4 23 238\n-----------------------------------\nlocal ID = zones[xi.zone.WINDURST_WATERS]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local makingHeadlines = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_HEADLINES)\n\n    if\n        player:hasKeyItem(xi.keyItem.NEW_MODEL_HAT) and\n        not utils.mask.getBit(player:getCharVar('QuestHatInHand_var'), 4)\n    then\n        player:messageSpecial(ID.text.YOU_SHOW_OFF_THE, 0, xi.keyItem.NEW_MODEL_HAT)\n        player:startEvent(60)\n    elseif makingHeadlines == xi.questStatus.QUEST_ACCEPTED then\n        -- bitmask of progress: 0 = Kyume-Romeh, 1 = Yuyuju, 2 = Hiwom-Gomoi, 3 = Umumu, 4 = Mahogany Door\n        local prog = player:getCharVar('QuestMakingHeadlines_var')\n\n        if not utils.mask.getBit(prog, 0) then\n            player:startEvent(668) -- Quest progress\n        else\n            player:startEvent(669) -- Quest not furthered\n        end\n    else\n        if math.randomInt(1, 100) <= 50 then\n            player:startEvent(604) -- Standard Conversation\n        else\n            player:startEvent(393) -- Standard Conversation\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 668 then\n        npcUtil.giveKeyItem(player, xi.keyItem.WINDURST_WATERS_SCOOP)\n        player:setCharVar('QuestMakingHeadlines_var', utils.mask.setBit(player:getCharVar('QuestMakingHeadlines_var'), 0, true))\n    elseif csid == 60 then\n        player:setCharVar('QuestHatInHand_var', utils.mask.setBit(player:getCharVar('QuestHatInHand_var'), 4, true))\n        player:incrementCharVar('QuestHatInHand_count', 1)\n    end\nend\n\nreturn entity\n"}};
